#define NUM_SIZE_CLASSES 16

// Structure used only when the memory chunk is free
typedef struct FreeChunk {
    struct FreeChunk* next; // Pointer to the next free chunk in this bin
    size_t size;            // Total size of the chunk (including header)
} FreeChunk;

// The segregated free lists (The Bins)
// Index i holds the head of the list for size class i.
FreeChunk* SegregatedBins[NUM_SIZE_CLASSES];

// Defines how requested size maps to a specific bin (size class)
// Typically logarithmic or based on powers of 2 (e.g., 8, 16, 32...)
int map_size_to_bin_index(size_t requested_size);

void* allocate(size_t s) {
    int index = map_size_to_bin_index(s);
    FreeChunk* block = SegregatedBins[index];
    // Search only the list pointed to by SegregatedBins[index]
    if (block) {
        SegregatedBins[index] = block->next;
        // Return payload address (block + sizeof(header))
        return (void*)block;
    }
    return NULL; // Request block from OS (if bins empty)
}
